RunOnUiAsync(() =>
            {
                foreach (var sub in subs)
                {
                    // Skip embedded entries — those are already in
                    // MediaPlaybackItem.TimedMetadataTracks via the container.
                    if (sub.Embedded) continue;
                    if (string.IsNullOrEmpty(sub.Path)) continue;

                    try
                    {
                        var tts = string.IsNullOrEmpty(sub.Language)
                            ? TimedTextSource.CreateFromUri(new Uri(sub.Path))
                            : TimedTextSource.CreateFromUri(new Uri(sub.Path), sub.Language);
                        source.ExternalTimedTextSources.Add(tts);

                        var stem = System.IO.Path.GetFileNameWithoutExtension(sub.Path);
                        _externalSubtitleLabels[sub.Path] = sub.Language ?? stem;
                    }
                    catch (Exception ex)
                    {
                        _logger?.LogDebug(ex, "Failed to attach persisted subtitle {Path}", sub.Path);
                    }
                }
            }).ConfigureAwait

dto.Lines.Select(l =>
        {
            var line = new ControlsLyricsLine
            {
                StartMs = l.StartMs,
                EndMs = l.EndMs,
                PrimaryText = l.PrimaryText,
                SecondaryText = l.SecondaryText ?? "",
                TertiaryText = l.TertiaryText ?? "",
                IsPrimaryHasRealSyllableInfo = l.HasSyllableSync,
                IsSectionHeader = l.IsSectionHeader,
            };

            if (l.PrimarySyllables != null)
            {
                line.PrimarySyllables = l.PrimarySyllables.Select(s => new ControlsBaseLyrics
                {
                    StartMs = s.StartMs,
                    EndMs = s.EndMs,
                    Text = s.Text,
                    StartIndex = s.StartIndex,
                }).ToList();
            }

            if (l.SecondarySyllables != null)
            {
                line.SecondarySyllables = l.SecondarySyllables.Select(s => new ControlsBaseLyrics
                {
                    StartMs = s.StartMs,
                    EndMs = s.EndMs,
                    Text = s.Text,
                    StartIndex = s.StartIndex,
                }).ToList();
            }

            return line;
        }).ToList

